mkitem!{mkimpl!{impl Compiler { pub (crate) fn set_cross_linker_and_runner (& mut self) { match self . triple . as_str () { "aarch64-unknown-linux-gnu" => { self . rustflags . push ("-Clinker=aarch64-linux-gnu-gcc" . to_owned ()) ; self . rustdocflags . push ("-Clinker=aarch64-linux-gnu-gcc" . to_owned ()) ; self . runner = vec ! ["qemu-aarch64" . to_owned () , "-L" . to_owned () , "/usr/aarch64-linux-gnu" . to_owned () ,] ; } "s390x-unknown-linux-gnu" => { self . rustflags . push ("-Clinker=s390x-linux-gnu-gcc" . to_owned ()) ; self . rustdocflags . push ("-Clinker=s390x-linux-gnu-gcc" . to_owned ()) ; self . runner = vec ! ["qemu-s390x" . to_owned () , "-L" . to_owned () , "/usr/s390x-linux-gnu" . to_owned () ,] ; } "riscv64gc-unknown-linux-gnu" => { self . rustflags . push ("-Clinker=riscv64-linux-gnu-gcc" . to_owned ()) ; self . rustdocflags . push ("-Clinker=riscv64-linux-gnu-gcc" . to_owned ()) ; self . runner = vec ! ["qemu-riscv64" . to_owned () , "-L" . to_owned () , "/usr/riscv64-linux-gnu" . to_owned () ,] ; } "x86_64-pc-windows-gnu" => { self . runner = vec ! ["wine" . to_owned ()] ; } _ => { eprintln ! ("Unknown non-native platform") ; } } } pub (crate) fn run_with_runner (& self , program : impl AsRef < OsStr >) -> Command { if self . runner . is_empty () { Command :: new (program) } else { let mut runner_iter = self . runner . iter () ; let mut cmd = Command :: new (runner_iter . next () . unwrap ()) ; cmd . args (runner_iter) ; cmd . arg (program) ; cmd } } }}}
