    copy_dir_recursively_introspect!();
    pub (crate) fn copy_dir_recursively (from : & Path , to : & Path) { for entry in fs :: read_dir (from) . unwrap () { let entry = entry . unwrap () ; let filename = entry . file_name () ; if filename == "." || filename == ".." { continue ; } let src = from . join (& filename) ; let dst = to . join (& filename) ; if entry . metadata () . unwrap () . is_dir () { fs :: create_dir (& dst) . unwrap_or_else (| e | panic ! ("failed to create {dst:?}: {e}")) ; copy_dir_recursively (& src , & dst) ; } else { fs :: copy (& src , & dst) . unwrap_or_else (| e | panic ! ("failed to copy {src:?}->{dst:?}: {e}")) ; } } }
